"نوفمبر\",\"ديسمبر\"];return `${d} ${M[m-1]}`;};\nconst TODAY=\"2026-10-11\";\nconst chain=(key,at)=>`<div class=\"chain\">${CHAINS[key].map((x,i)=>`<span class=\"${i<at?\"done\":i===at?\"at\":\"\"}\">${x}</span>`).join(\"\")}</div>`;\nconst proofLine=(a)=>`<div class=\"proof\"><span class=\"${a.yes?\"y\":\"n\"}\">${a.yes?\"نعم\":\"لسه\"}</span><span>${esc(a.q)}</span><span class=\"ev\">· ${esc(a.note)}</span></div>`;\n\nfunction go(level,arm,sec){ view={level,arm:arm||null,sec:sec||null}; try{ history.replaceState(null,\"\", level===\"map\"?\"#\":VIEWS[level]?\"#\"+level:\"#\"+arm+(sec?\".\"+sec:\"\")); }catch(e){} render(); window.scrollTo({top:0}); }\n\n// ---------- RENDER ----------\nfunction renderSide(){\n  const tot=allNeed().length;\n  $(\"#side\").innerHTML = `\n    <div class=\"brand\">VisionSeek <small>غرفة العمليات</small></div>\n    <button class=\"nav ${view.level===\"map\"?\"on\":\"\"}\" onclick=\"go('map')\"><span class=\"dot\" style=\"background:var(--fg)\"></span>الخريطة<span class=\"n ${tot?'need':''}\">${tot||\"\"}</span></button>\n    <div class=\"grp\">عرض</div>\n    ${Object.entries(VIEWS).map(([k,v])=>`<button class=\"nav ${view.level===k?\"on\":\"\"}\" onclick=\"go('${k}')\"><span class=\"dot\" style=\"background:var(--line)\"></span>${v}${k===\"decisions\"&&oneWayNeed().length?`<span class=\"n need\">${oneWayNeed().length}</span>`:\"\"}</button>`).join(\"\")}\n    <div class=\"grp\">الأذرع</div>\n    ${ARMS.map(a=>`<button class=\"nav ${view.arm===a.id?\"on\":\"\"}\" onclick=\"go('arm','${a.id}')\"><span class=\"dot\" style=\"background:${a.color}\"></span>${a.name}<span class=\"n ${needCount(a.id)?'need':''}\">${needCount(a.id)||\"\"}</span></button>`).join(\"\")}\n    <div class=\"foot\"><div class=\"live ${(LIVE||LIVEDATA)?\"on\":\"\"}\"><i></i>${LIVEDATA?\"حي من Notion · \"+String(LIVEDATA.at).slice(11,16)+\" UTC\":LIVE?(DB?\"متصل · تقدر تعدّل من هنا\":\"متصل · قراءة\"):\"لقطة Notion\"}</div>الذاكرة في Notion · الإصدار 3 · قراءة حيّة + تشغيل · 11 أكتوبر 2026<br><a href=\"${NOTION.root}\" target=\"_blank\" rel=\"noreferrer\">افتح القواعد</a> · <a href=\"/ops/logout\">خروج</a></div>`;\n}\n\nfunction needStrip(list){\n  if(!list.length) return `<div class=\"need-strip\" style=\"border-color:var(--line)\"><span class=\"tag\" style=\"color:var(--ok)\">مفيش حاجة مستنياك</span></div>`;\n  return `<div class=\"need-strip\"><span class=\"tag\">مستنيك · ${list.length}</span><ul>${list.map(c=>`<li><span class=\"k\">${esc(c.kind)}</span><span>${esc(c.t)}</span></li>`).join(\"\")}</ul></div>`;\n}\n\nfunction renderMap(){\n  $(\"#main\").innerHTML = `\n    <div class=\"crumb\">المستوى 1</div>\n    <h1>VisionSeek</h1>\n    <p class=\"lede\">${esc(POSITIONING)}</p>\n    ${needStrip(allNeed())}\n    ${(()=>{const d=CARDS.filter(c=>c.kind===\"قرار\"&&c.st===\"wait\"&&c.on);return d.length?`<div class=\"wip\"><span>مؤجل بتاريخ مراجعة:</span>${d.map(c=>`<span><b>${fmtD(c.on)}</b> ${esc(c.t.split(\" — \")[0])}</span>`).join(\"\")}</div>`:\"\"})()}\n    <h2>الآن <span class=\"clock\">${esc(NOW.clock)} · سؤال واحد</span></h2>\n    <div class=\"now\"><div class=\"q\">${esc(NOW.q)}</div>${chain(NOW.chain,NOW.at)}<div class=\"ev ${NOW.ev?\"\":\"none\"}\">${NOW.ev?\"<b>الدليل:</b> \"+esc(NOW.ev):\"الدليل: لسه مفيش. الحزمة جاهزة ومعتمدة؛ أول خطوة الاتنين 12: أول 10 أسماء + الرسايل.\"}</div>${DB?`<div class=\"ctl\"><select id=\"now-at\">${CHAINS[NOW.chain].map((x,i)=>`<option value=\"${i}\" ${NOW.at===i?\"selected\":\"\"}>${x}</option>`).join(\"\")}</select><input id=\"now-ev\" placeholder=\"الدليل (إيصال، رسالة، رابط)\" value=\"${esc(NOW.ev||\"\")}\"><button class=\"b\" onclick=\"saveNow()\">احفظ</button></div>`:\"\"}</div>\n    ${LOG.length?`<h2>آخر الحركات <span class=\"clock\">من الصفحة نفسها</span></h2><div class=\"log\">${LOG.slice(0,6).map(r=>`<div class=\"r\"><span class=\"d\">${esc(r.t)}</span><span>${esc(r.x)}</span></div>`).join(\"\")}</div>`:\"\"}\n    <h2>النبض <span class=\"clock\">كل خميس · يرى · يعرف · يربط</span></h2>\n    <div class=\"goals\">${PULSE.map(g=>`<div class=\"goal\"><div class=\"big\">${g.items.length}<small>${esc(g.m)}</small></div><div class=\"t\" style=\"margin-top:8px\">${esc(g.k)}</div><ul>${g.items.map(i=>`<li><span class=\"src\">${esc(i.src)}</span>${i.l?`<a href=\"${i.l}\" target=\"_blank\" rel=\"noreferrer\">${esc(i.t)}</a>`:esc(i.t)}</li>`).join(\"\")}</ul></div>`).join(\"\")}</div>\n    <h2>المؤسسة <span class=\"clock\">HLO · سؤال الاتجاه</span></h2>\n    <div class=\"now\"><div class=\"q\">${esc(HLO_Q.q)}</div><div class=\"ev\">${HLO_Q.items.map(esc).join(\" · \")}</div></div>\n    <h2>الأذرع الخمسة · المستوى 2</h2>\n    <div class=\"arms\">${ARMS.map(a=>{const cs=cardsFor(a.id);const n=needCount(a.id);return `<button class=\"arm\" style=\"--ac:${a.color}\" onclick=\"go('arm','${a.id}')\"><div class=\"t\">${esc(a.name)}</div><div class=\"d\">${esc(a.desc)}</div>${proofLine(a)}<div class=\"s\"><span><b>${a.secs.length}</b> أقسام</span>${n?`<span><b class=\"need\">${n}</b> مستنيك</span>`:\"\"}</div></button>`}).join(\"\")}</div>\n    <h2>الممارسات المدمجة في الغرفة <span class=\"clock\">من الشركات العالمية · اللي يمشي مع فلسفتنا بس</span></h2>\n    <div class=\"prac\">${PRACTICES.map(p=>`<div class=\"p\"><b>${esc(p.n)}</b><small>${esc(p.src)}</small><span class=\"w\">${esc(p.w)}</span></div>`).join(\"\")}</div>\n    <div class=\"meta\"><span>تنزل بالضغط. <kbd>Esc</kbd> ترجع.</span><a href=\"${NOTION.map}\" target=\"_blank\" rel=\"noreferrer\">الخريطة في Notion</a><a href=\"${NOTION.decisions}\" target=\"_blank\" rel=\"noreferrer\">القرارات</a><a href=\"${NOTION.work}\" target=\"_blank\" rel=\"noreferrer\">الشغل</a><a href=\"${NOTION.publish}\" target=\"_blank\" rel=\"noreferrer\">النشر</a></div>`;\n}\n\nfunction renderArm(){\n  const a=armOf(view.arm);\n  $(\"#main\").innerHTML = `\n    <div class=\"crumb\"><button onclick=\"go('map')\">الخريطة</button> › المستوى 2</div>\n    <h1 style=\"color:${a.color}\">${esc(a.name)}</h1>\n    <p class=\"lede\">${esc(a.desc)}</p>\n    <div class=\"now\"><div class=\"q\">سؤال الدليل <span class=\"clock\">كل خميس</span></div>${proofLine(a)}</div>\n    ${a.id===\"eng\"?engineBlock():\"\"}\n    ${needStrip(cardsFor(a.id).filter(c=>c.st===\"need\"))}\n    <h2>الأقسام · المستوى 3</h2>\n    <div class=\"secs\">${a.secs.map(s=>{const cs=cardsFor(a.id,s.id);const n=cs.filter(c=>c.st===\"need\").length;return `<button class=\"sec\" onclick=\"go('sec','${a.id}','${s.id}')\"><div class=\"t\">${esc(s.name)}</div><div class=\"d\">${esc(s.desc)}</div><div class=\"s\">${cs.length} كروت${n?` · <span class=\"need\">${n} مستنيك</span>`:\"\"}</div></button>`}).join(\"\")}</div>`;\n}\n\nfunction renderSec(){\n  const a=armOf(view.arm); const s=a.secs.find(x=>x.id===view.sec);\n  const cs=cardsFor(a.id,s.id);\n  const L=(h,b)=>`<div class=\"layer\"><div class=\"h\">${h}</div><div class=\"b ${(!b||b===\"—\")?\"empty\":\"\"}\">${esc((!b||b===\"—\")?\"لم يُكتب بعد\":b)}</div></div>`;\n  $(\"#main\").innerHTML = `\n    <div class=\"crumb\"><button onclick=\"go('map')\">الخريطة</button> › <button onclick=\"go('arm','${a.id}')\">${esc(a.name)}</button> › المستوى 3</div>\n    <h1>${esc(s.name)}</h1>\n    <p class=\"lede\">${esc(s.desc)}</p>\n    <div class=\"layers\">${L(\"المنهجية · إزاي بنشتغل\",s.method)}${L(\"الأسلوب · إزاي بننشر ونصوّر ونكتب\",s.style)}${L(\"الذكاء · المحركات والأدوات\",s.ai)}${L(\"الدليل · إزاي نعرف إننا شغالين\",s.proof)}</div>\n    ${s.id===\"sprint\"?`<div class=\"pm\"><div class=\"h\">${esc(PREMORTEM.h)}</div><ol>${PREMORTEM.q.map(q=>`<li>${esc(q)}</li>`).join(\"\")}</ol><div class=\"f\">${esc(PREMORTEM.f)}</div></div>`:\"\"}\n    <h2>التاسكات · المستوى 4</h2>\n    <div class=\"cards\">${cs.length?cs.sort((x,y)=>(x.st===\"need\"?0:1)-(y.st===\"need\"?0:1)).map(c=>`<div class=\"card\"><span class=\"pill ${c.st}\">${lbl(c)}</span><div><div class=\"t\">${esc(c.t)}</div>${c.d?`<div class=\"d\">${esc(c.d)}</div>`:\"\"}${c.chain?chain(c.chain,c.at):\"\"}${c.nx?`<div class=\"nx\"><b>الخطوة الجاية:</b> ${esc(c.nx)}</div>`:\"\"}${c.lev?`<div class=\"nx\"><b>الرافعة:</b> ${esc(c.lev)}</div>`:\"\"}${c.fin?`<div class=\"note\"><b>القرار النهائي:</b> ${esc(c.fin)}</div>`:\"\"}${c.note?`<div class=\"note\">${esc(c.note)}</div>`:\"\"}${ctl(c)}${c.lnk?`<a class=\"lnk\" href=\"${c.lnk}\" target=\"_blank\" rel=\"noreferrer\">الصفحة في Notion</a>`:\"\"}</div><div class=\"who\">${esc(c.kind)} · ${esc(c.who)}${c.app?`<br>شهية: ${esc(c.app)}`:\"\"}${c.door?`<br>باب ${c.door===\"one\"?\"ما يرجعش\":\"يرجع فيه\"}`:\"\"}</div></div>`).join(\"\"):`<div class=\"empty\">مفيش تاسكات هنا دلوقتي.</div>`}</div>`;\n}\n\nfunction head(t,sub){ return `<div class=\"crumb\"><button onclick=\"go('map')\">الخريطة</button> › عرض</div><h1>${t}</h1><p class=\"lede\">${sub}</p>`; }\nfunction kc(c){ const a=armOf(c.arm); return `<button class=\"kc\" style=\"--ac:${a.color}\" onclick=\"go('sec','${c.arm}','${c.sec}')\"><div class=\"t\">${esc(c.t)}</div><div class=\"m\"><span>${esc(a.name)}</span>${c.app?`<span>شهية: ${esc(c.app)}</span>`:\"\"}${c.on?`<span>${fmtD(c.on)}</span>`:\"\"}</div></button>`; }\nfunction renderKanban(){\n  const w=wip(); const cols=[[\"need\",\"مستنيك\"],[\"ok\",\"شغال\"],[\"wait\",\"في الطابور\"],[\"hold\",\"واقف\"]];\n  $(\"#main\").innerHTML = head(\"الكانبان\",\"كل الكروت في عمود حالتها. حد الشغل الجاري: \"+WIP_LIMIT+\" لكل منفّذ (Toyota).\")+\n    `<div class=\"wip\"><span>شغال دلوقتي:</span>${Object.entries(w).map(([o,n])=>`<span><b>${esc(o)}</b> ${n}/${WIP_LIMIT}${n>WIP_LIMIT?` <span class=\"over\">فوق الحد</span>`:\"\"}</span>`).join(\"\")||\"<span>لا شيء</span>\"}</div>\n    <div class=\"kan\">${cols.map(([k,l])=>{const cs=CARDS.filter(c=>c.st===k);return `<div class=\"col ${k===\"need\"?\"need\":\"\"}\"><div class=\"h\"><span>${l}</span><span class=\"n\">${cs.length}</span></div>${cs.map(kc).join(\"\")||`<div class=\"ev none\">—</div>`}</div>`}).join(\"\")}</div>`;\n}\nfunction renderCal(){\n  const items=[...CARDS.filter(c=>c.on).map(c=>({on:c.on,kind:(c.kind===\"قرار\"&&c.st===\"wait\")?\"مراجعة قرار مؤجل\":c.kind,t:c.t,st:c.st,arm:c.arm,sec:c.sec})),...EVENTS].sort((a,b)=>a.on.localeCompare(b.on));\n  const wk=(iso)=>{const d=new Date(iso+\"T00:00:00Z\");const s=new Date(d);s.setUTCDate(d.getUTCDate()-((d.getUTCDay()+1)%7));return s.toISOString().slice(0,10);};\n  let last=\"\"; let html=\"\";\n  items.forEach(i=>{const k=wk(i.on); if(k!==last){last=k;html+=`<div class=\"wk\">أسبوع ${fmtD(k)}</div>`;} html+=`<div class=\"row ${i.on===TODAY?\"today\":\"\"}\"><span class=\"d\">${fmtD(i.on)}</span><span class=\"k\">${esc(i.kind)}</span><span class=\"t\">${i.arm?`<button style=\"padding:0;text-align:start\" onclick=\"go('sec','${i.arm}','${i.sec}')\">${esc(i.t)}</button>`:esc(i.t)}${i.st?`<span class=\"pill ${i.st}\">${ST[i.st]}</span>`:\"\"}</span></div>`;});\n  $(\"#main\").innerHTML = head(\"التقويم\",\"كل حاجة لها تاريخ: نشر، مواعيد، إيقاع الخميس، والساعة الكبيرة.\")+`<div class=\"tl\">${html}</div>`;\n}\nfunction flow(h,d,nodes,color){ return `<div class=\"flow\" style=\"--ac:${color||\"var(--fg)\"}\"><div class=\"h\">${h}</div><div class=\"d\">${d}</div><div class=\"fl\">${nodes.map((n,i)=>`${i?'<span class=\"ar\">←</span>':''}<div class=\"nd ${n.hi?\"hi\":\"\"}\"><b>${esc(n.b)}</b>${n.s?`<small>${esc(n.s)}</small>`:\"\"}</div>`).join(\"\")}</div></div>`; }\nfunction radial(){\n  const R=200,cx=320,cy=200,r=130; const pts=ARMS.map((a,i)=>{const t=-Math.PI/2+i*2*Math.PI/ARMS.length;return {a,x:cx+r*Math.cos(t),y:cy+r*Math.sin(t)}});\n  return `<svg class=\"radial\" viewBox=\"0 0 640 400\" role=\"img\" aria-label=\"خريطة الأذرع\">${pts.map(p=>`<line class=\"ln\" x1=\"${cx}\" y1=\"${cy}\" x2=\"${p.x}\" y2=\"${p.y}\" stroke-width=\"1\"/>`).join(\"\")}<circle class=\"c\" cx=\"${cx}\" cy=\"${cy}\" r=\"46\" stroke-width=\"1.5\"/><text x=\"${cx}\" y=\"${cy-4}\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\">VisionSeek</text><text class=\"sm\" x=\"${cx}\" y=\"${cy+14}\" text-anchor=\"middle\">يرى · يعرف · يربط</text>${pts.map(p=>`<g style=\"cursor:pointer\" onclick=\"go('arm','${p.a.id}')\"><circle class=\"c\" cx=\"${p.x}\" cy=\"${p.y}\" r=\"40\" stroke=\"${p.a.color}\" stroke-width=\"2\"/><text x=\"${p.x}\" y=\"${p.y-2}\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">${esc(p.a.name.split(\" و\")[0].split(\" \")[0])}</text><text class=\"sm\" x=\"${p.x}\" y=\"${p.y+14}\" text-anchor=\"middle\">${p.a.secs.length} أقسام${needCount(p.a.id)?\" · \"+needCount(p.a.id)+\" مستنيك\":\"\"}</text></g>`).join(\"\")}</svg>`;\n}\nfunction renderFlows(){\n  $(\"#main\").innerHTML = head(\"الخرائط\",\"المؤسسة كرسم، وكل مسار بنشتغل بيه كتدفق. الأذرع شغالة بالتوازي، والأسهم جوه كل ذراع بس.\")+radial()+\n    flow(\"دورة المحركات\",\"كل أسبوع. الناتج فكرة واحدة ببطاقة تنفيذ.\",[{b:\"رادار الفرص\",s:\"الطلب\"},{b:\"رادار القدرات\",s:\"الإمكانية\"},{b:\"التقاطع\",s:\"فين بيلتقوا\"},{b:\"المعالج\",s:\"5 أشكال\"},{b:\"بطاقة تنفيذ\",s:\"معيار إيقاف\",hi:true},{b:\"درس\",s:\"AAR\"}],\"var(--arm-eng)\")+\n    flow(\"مسار العميل\",\"6 مراحل. «مش دلوقتي» إجابة محترمة. الدليل في كل مرحلة رسالة أو إيصال.\",[{b:\"إشارة\",s:\"من الرادارين\"},{b:\"تواصل\",s:\"رسالة واحدة\"},{b:\"لقاء\",s:\"20 دقيقة\"},{b:\"مدفوع\",s:\"جلسة القائد\",hi:true},{b:\"أعمق\",s:\"سبرنت\"},{b:\"مستمر\",s:\"ماستر كلاس / HLO\"}],\"var(--arm-mkt)\")+\n    flow(\"سلّم العروض\",\"كل عرض يبني أساس اللي بعده.\",[{b:\"جلسة القائد\",s:\"90 دقيقة · 1,000 درهم\"},{b:\"سبرنت الوظيفة\",s:\"5 أيام · 7,500 درهم\"},{b:\"ماستر كلاس\",s:\"12 قطاع\"},{b:\"HLO\",s:\"رفع المؤسسة\"}],\"var(--arm-edu)\")+\n    flow(\"النشر\",\"Claude يكتب، د. أحمد يراجع مرة واحدة، والرابط بعد النشر دليل.\",[{b:\"مسودة\",s:\"Claude · الأحد\"},{b:\"مراجعة\",s:\"د. أحمد\",hi:true},{b:\"معتمد\"},{b:\"منشور\",s:\"LinkedIn / X\"},{b:\"رابط\",s:\"الدليل\"}],\"var(--arm-mkt)\")+\n    flow(\"القرار\",\"بابين: اللي يرجع فيه يتاخد ويتبلّغ؛ اللي ما يرجعش يستنّى د. أحمد.\",[{b:\"سؤال\"},{b:\"باب؟\",s:\"يرجع فيه / لا\"},{b:\"يرجع فيه\",s:\"Claude ياخده ويبلّغ\"},{b:\"ما يرجعش\",s:\"مستنيك\",hi:true},{b:\"سجل\",s:\"بالسبب والتاريخ\"}],\"var(--arm-adm)\");\n}\nfunction renderLessons(){\n  $(\"#main\").innerHTML = head(\"الدروس · المراجعة بعد الفعل\",\"بعد كل دورة أو جلسة: 4 أسئلة، وآخرها درس بسطر واحد يُقرأ قبل الدورة الجاية.\")+\n    [...EXTRA_AAR,...AAR].map(a=>`<div class=\"aar\"><div class=\"t\">${esc(a.t)}<small>${esc(a.on)}</small></div><dl><dt>إيه المتوقع؟</dt><dd>${esc(a.exp)}</dd><dt>إيه اللي حصل؟</dt><dd>${esc(a.got)}</dd><dt>ليه الفرق؟</dt><dd>${esc(a.why)}</dd><dt>نعمل إيه المرة الجاية؟</dt><dd>${esc(a.next)}</dd></dl><div class=\"lesson\">درس: ${esc(a.lesson)}</div></div>`).join(\"\")+\n    (DB?`<div class=\"aar\"><div class=\"t\">درس جديد</div><div class=\"ctl\" style=\"display:grid;grid-template-columns:1fr;gap:6px\"><input id=\"aar-t\" placeholder=\"عن إيه؟ (دورة، جلسة، بوست)\"><input id=\"aar-exp\" placeholder=\"إيه المتوقع؟\"><input id=\"aar-got\" placeholder=\"إيه اللي حصل؟\"><input id=\"aar-why\" placeholder=\"ليه الفرق؟\"><input id=\"aar-next\" placeholder=\"نعمل إيه المرة الجاية؟\"><input id=\"aar-lesson\" placeholder=\"الدرس في سطر\"><div><button class=\"b\" onclick=\"saveAAR()\">احفظ الدرس</button></div></div></div>`:\"\")+\n    `<div class=\"meta\"><a href=\"https://app.notion.com/p/3f3e8808b7a6810c8e62d763e09230ac\" target=\"_blank\" rel=\"noreferrer\">ذاكرة الماكينة — الدروس في Notion</a></div>`;\n}\nfunction renderDecisions(){\n  const ord={need:0,wait:1,ok:2,hold:3}; const ds=CARDS.filter(c=>c.kind===\"قرار\").sort((x,y)=>ord[x.st]-ord[y.st]);\n  $(\"#main\").innerHTML = head(\"القرارات\",\"بابين (Bezos): الباب اللي يرجع فيه Claude ياخده ويبلّغك؛ الباب اللي ما يرجعش هو بس اللي يستناك. القرار المؤجل له تاريخ مراجعة في التقويم — ما فيش قرار يتنسي. السجل يُضاف إليه ولا يُعدَّل.\")+\n    `<div class=\"tabwrap\"><table class=\"dtab\"><thead><tr><th>القرار</th><th>الباب</th><th>الحالة</th><th>السبب / الرأي</th></tr></thead><tbody>${ds.map(c=>`<tr><td><button style=\"padding:0;text-align:start;font-weight:600\" onclick=\"go('sec','${c.arm}','${c.sec}')\">${esc(c.t)}</button></td><td><span class=\"door ${c.door}\">${c.door===\"one\"?\"ما يرجعش\":\"يرجع فيه\"}</span></td><td><span class=\"pill ${c.st}\">${lbl(c)}</span><div class=\"ev\" style=\"margin-top:4px\">${esc(c.who)}${c.st===\"wait\"&&c.on?`<br><b>يُراجع ${fmtD(c.on)}</b>`:\"\"}</div></td><td class=\"ev\">${esc(c.d||\"—\")}</td></tr>`).join(\"\")}</tbody></table></div>`;\n}\nfunction ctl(c){\n  if(!DB) return \"\";\n  const id=c.id, opts=Object.keys(ST).map(k=>`<option value=\"${k}\" ${c.st===k?\"selected\":\"\"}>${lbl(c,k)}</option>`).join(\"\");\n  const chainOpts=c.chain?`<select id=\"at-${id}\">${CHAINS[c.chain].map((x,i)=>`<option value=\"${i}\" ${c.at===i?\"selected\":\"\"}>${x}</option>`).join(\"\")}</select>`:\"\";\n  const dec=c.kind===\"قرار\"?`<input id=\"fin-${id}\" placeholder=\"القرار النهائي\" value=\"${esc(c.fin||\"\")}\">`:\"\";\n  const quick=c.kind===\"نشر\"?`<button class=\"b ok\" onclick=\"quickSt('${id}','ok','اعتمد')\">اعتمد</button><button class=\"b no\" onclick=\"quickSt('${id}','hold','رفض')\">ارفض</button>`:\"\";\n  return `<div class=\"ctl\"><select id=\"st-${id}\">${opts}</select>${chainOpts}${dec}<input id=\"nt-${id}\" placeholder=\"ملاحظة أو دليل (رابط، رسالة…)\" value=\"${esc(c.note||\"\")}\"><button class=\"b\" onclick=\"saveCard('${id}')\">احفظ</button>${quick}<span id=\"ok-${id}\"></span></div>`;\n}\nasync function saveCard(id){ const c=CARDS.find(x=>x.id===id); if(!c)return; const st=$(\"#st-\"+id).value, note=$(\"#nt-\"+id).value.trim(); const atEl=$(\"#at-\"+id), finEl=$(\"#fin-\"+id); const patch={st,note}; if(atEl)patch.at=Number(atEl.value); if(finEl)patch.fin=finEl.value.trim(); if(c.kind===\"قرار\"&&patch.fin&&st===\"need\")patch.st=\"ok\"; const o=$(\"#ok-\"+id); if(o)o.textContent=\"…\"; await saveState(id,patch,`${c.kind}: ${c.t} → ${lbl(c,patch.st)}${patch.fin?\" · \"+patch.fin:\"\"}${note?\" · \"+note:\"\"}`); if(o){o.textContent=\"اتحفظ\";o.className=\"saved\";} }\nasync function quickSt(id,st,word){ const c=CARDS.find(x=>x.id===id); if(!c)return; await saveState(id,{st},`${word}: ${c.t}`); }\nasync function saveNow(){ const at=Number($(\"#now-at\").value), ev=$(\"#now-ev\").value.trim(); await saveState(\"now\",{at,ev},`الآن: ${CHAINS[NOW.chain][at]}${ev?\" · \"+ev:\"\"}`); }\nasync function saveAAR(){ const g=(k)=>($(\"#aar-\"+k).value||\"\").trim(); const a={t:g(\"t\"),on:nowISO().slice(0,10),exp:g(\"exp\"),got:g(\"got\"),why:g(\"why\"),next:g(\"next\"),lesson:g(\"lesson\")}; if(!a.t||!a.lesson)return; await addAAR(a); }\nfunction engineBlock(){\n  const flash=ROOM&&ROOM.flash?`<div class=\"flash ${/ما قدرناش/.test(ROOM.flash)?\"err\":\"\"}\">${esc(ROOM.flash)}</div>`:\"\";\n  const cyc=LIVEDATA&&LIVEDATA.cycles&&LIVEDATA.cycles.length?`<div class=\"now\"><div class=\"q\">آخر الدورات <span class=\"clock\">حي من Notion</span></div><div class=\"cyc\">${LIVEDATA.cycles.slice(0,8).map(c=>`<div class=\"r\"><span class=\"d\">${fmtD(c.edited)}</span><a href=\"${esc(c.url)}\" target=\"_blank\" rel=\"noreferrer\">${esc(c.title)}</a></div>`).join(\"\")}</div></div>`:\"\";\n  const rq=LIVEDATA&&LIVEDATA.requests?LIVEDATA.requests:[];\n  const rqst={\"جديد\":\"need\",\"شغال\":\"ok\",\"اتعمل\":\"done\",\"فشل\":\"hold\"};\n  const reqs=rq.length?`<div class=\"cyc\" style=\"margin-top:10px\">${rq.slice(0,6).map(r=>`<div class=\"r\"><span class=\"pill ${rqst[r[\"الحالة\"]]||\"wait\"}\">${esc(r[\"الحالة\"]||\"\")}</span><span>${esc(r[\"الطلب\"]||\"\")}</span>${r[\"النتيجة\"]?`<a href=\"${esc(r[\"النتيجة\"])}\" target=\"_blank\" rel=\"noreferrer\">النتيجة</a>`:\"\"}</div>`).join(\"\")}</div>`:`<div class=\"ev none\" style=\"margin-top:8px\">مفيش طلبات لسه.</div>`;\n  const form=ON_SITE?`<form class=\"runf\" method=\"post\" action=\"/ops/run\"><select name=\"engine\"><option>الدورة كاملة</option><option>رادار الفرص</option><option>رادار القدرات</option><option>المعالج</option></select><input name=\"note\" placeholder=\"توجيه للدورة دي (اختياري): قطاع، دولة، سؤال…\" maxlength=\"600\"><button type=\"submit\">شغّل دورة</button><div class=\"ev none\">الطلب يتسجّل في Notion، ومهمة مجدولة تلقطه خلال ساعة وتكتب النتيجة هنا.</div></form>`:`<div class=\"ev none\" style=\"margin-top:8px\">زرار «شغّل دورة» شغال من نسخة الموقع (visionseek.org/ops).</div>`;\n  return flash+cyc+`<div class=\"now\"><div class=\"q\">تشغيل المحرك <span class=\"clock\">المستوى 2</span></div>${reqs}${form}</div>`;\n}\nfunction render(){ renderSide(); if(view.level===\"map\")renderMap(); else if(view.level===\"kanban\")renderKanban(); else if(view.level===\"cal\")renderCal(); else if(view.level===\"flows\")renderFlows(); else if(view.level===\"lessons\")renderLessons(); else if(view.level===\"decisions\")renderDecisions(); else if(view.level===\"arm\")renderArm(); else renderSec(); }\ndocument.addEventListener(\"keydown\",e=>{ if(e.key===\"Escape\"){ if(view.level===\"sec\")go('arm',view.arm); else if(view.level!==\"map\")go('map'); } });\nrender();\n</script>\n\n</body>\n</html>\n";
